-- Forward-only conversion: refuses to merge independent businesses.
PRAGMA defer_foreign_keys=ON;
CREATE TABLE _single_business_guard(n INTEGER NOT NULL CHECK(n<=1));
INSERT INTO _single_business_guard SELECT COUNT(*) FROM tenants;
DROP TABLE _single_business_guard;
CREATE TABLE _profile_copy AS SELECT settings,created_at FROM tenants LIMIT 1;
CREATE TABLE _copy_members AS SELECT * FROM members;
CREATE TABLE _copy_records AS SELECT * FROM records;
CREATE TABLE _copy_products AS SELECT * FROM products;
CREATE TABLE _copy_units AS SELECT * FROM units;
CREATE TABLE _copy_customers AS SELECT * FROM customers;
CREATE TABLE _copy_bookings AS SELECT * FROM bookings;
CREATE TABLE _copy_items AS SELECT * FROM items;
CREATE TABLE _copy_reservations AS SELECT * FROM reservations;
CREATE TABLE _copy_payments AS SELECT * FROM payments;
CREATE TABLE _copy_ledger AS SELECT * FROM ledger;
CREATE TABLE _copy_status_logs AS SELECT * FROM status_logs;
CREATE TABLE _copy_audit AS SELECT * FROM audit;
CREATE TABLE _copy_uploads AS SELECT * FROM uploads;
CREATE TABLE _copy_rate_limits AS SELECT * FROM rate_limits;
CREATE TABLE _copy_operation_keys AS SELECT * FROM operation_keys;
DROP TABLE platform_announcements;
DROP TABLE billing_invoices;
DROP TABLE plans;
DROP TABLE operation_keys;
DROP TABLE rate_limits;
DROP TABLE uploads;
DROP TABLE audit;
DROP TABLE status_logs;
DROP TABLE ledger;
DROP TABLE payments;
DROP TABLE reservations;
DROP TABLE items;
DROP TABLE bookings;
DROP TABLE customers;
DROP TABLE units;
DROP TABLE products;
DROP TABLE records;
DROP TABLE platform_admins;
DROP TABLE members;
DROP TABLE tenants;
CREATE TABLE store_profile(id INTEGER PRIMARY KEY CHECK(id=1),name TEXT NOT NULL DEFAULT 'Radix Outdoor',timezone TEXT NOT NULL DEFAULT 'Asia/Jakarta',currency TEXT NOT NULL DEFAULT 'IDR' CHECK(currency='IDR'),settings_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
INSERT INTO store_profile(id,name,settings_json,created_at,updated_at) VALUES(1,'Radix Outdoor',COALESCE((SELECT settings FROM _profile_copy),'{}'),COALESCE((SELECT created_at FROM _profile_copy),0),0);
DROP TABLE _profile_copy;
CREATE TABLE users(id TEXT PRIMARY KEY,  password_hash TEXT,last_login_at INTEGER,user_id TEXT, email TEXT NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL, outlet_id TEXT, partner_id TEXT, active INTEGER NOT NULL DEFAULT 1, UNIQUE(email),CHECK(role IN('owner','admin','warehouse','partner')));
CREATE TABLE records(id TEXT PRIMARY KEY,kind TEXT NOT NULL,data TEXT NOT NULL,deleted_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE products(id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,brand TEXT,description TEXT,price INTEGER NOT NULL CHECK(price>=0),image TEXT,capacity INTEGER NOT NULL DEFAULT 1,buffer_hours INTEGER, published INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,created_at INTEGER NOT NULL, images TEXT NOT NULL DEFAULT '[]');
CREATE TABLE units(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),outlet_id TEXT NOT NULL,code TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'available',condition_note TEXT,purchase_price INTEGER NOT NULL DEFAULT 0,partner_id TEXT,created_at INTEGER NOT NULL,UNIQUE(code));
CREATE TABLE customers(id TEXT PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT,address TEXT,id_doc TEXT,blacklisted INTEGER NOT NULL DEFAULT 0,notes TEXT,segment TEXT NOT NULL DEFAULT 'baru',created_at INTEGER NOT NULL,UNIQUE(phone));
CREATE TABLE bookings(id TEXT PRIMARY KEY,outlet_id TEXT NOT NULL,customer_id TEXT NOT NULL REFERENCES customers(id),code TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending_payment',channel TEXT NOT NULL,start_at INTEGER NOT NULL,end_at INTEGER NOT NULL,subtotal INTEGER NOT NULL,discount INTEGER NOT NULL DEFAULT 0,total INTEGER NOT NULL CHECK(total>=0),paid INTEGER NOT NULL DEFAULT 0 CHECK(paid>=0 AND paid<=total),dp INTEGER NOT NULL DEFAULT 0,expires_at INTEGER,collateral TEXT NOT NULL DEFAULT 'none',collateral_type TEXT,note TEXT,idem TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(code),UNIQUE(idem));
CREATE TABLE items(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES bookings(id),product_id TEXT NOT NULL,unit_id TEXT NOT NULL REFERENCES units(id),product_name TEXT NOT NULL,price INTEGER NOT NULL,days INTEGER NOT NULL,total INTEGER NOT NULL,returned_at INTEGER,condition TEXT, voided_at INTEGER);
CREATE TABLE reservations(id TEXT PRIMARY KEY,unit_id TEXT NOT NULL REFERENCES units(id),booking_id TEXT,start_at INTEGER NOT NULL,end_at INTEGER NOT NULL,kind TEXT NOT NULL DEFAULT 'booking',released_at INTEGER,CHECK(end_at>start_at));
CREATE TABLE payments(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES bookings(id),amount INTEGER NOT NULL CHECK(amount>0),method TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'rental',status TEXT NOT NULL DEFAULT 'pending',proof TEXT,idem TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(idem));
CREATE TABLE ledger(id TEXT PRIMARY KEY,booking_id TEXT,account TEXT NOT NULL,direction TEXT NOT NULL CHECK(direction IN('in','out')),amount INTEGER NOT NULL CHECK(amount>0),reference TEXT UNIQUE,note TEXT,created_at INTEGER NOT NULL);
CREATE TABLE status_logs(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL,status TEXT NOT NULL,note TEXT,created_at INTEGER NOT NULL);
CREATE TABLE audit(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT,ip TEXT,created_at INTEGER NOT NULL);
CREATE TABLE uploads(id TEXT PRIMARY KEY,kind TEXT NOT NULL,owner_token TEXT NOT NULL,mime TEXT NOT NULL,created_at INTEGER NOT NULL,storage_key TEXT,storage_bucket TEXT NOT NULL DEFAULT 'private' CHECK(storage_bucket IN('private','public')));
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE operation_keys(key TEXT NOT NULL,PRIMARY KEY(key));
INSERT INTO users(id,user_id,email,name,role,outlet_id,partner_id,active) SELECT id,user_id,email,name,role,outlet_id,partner_id,active FROM _copy_members;
DROP TABLE _copy_members;
INSERT INTO records(id,kind,data,deleted_at,created_at) SELECT id,kind,data,deleted_at,created_at FROM _copy_records;
DROP TABLE _copy_records;
INSERT INTO products(id,name,category,brand,description,price,image,capacity,buffer_hours,published,deleted_at,created_at,images) SELECT id,name,category,brand,description,price,image,capacity,buffer_hours,published,deleted_at,created_at,images FROM _copy_products;
DROP TABLE _copy_products;
INSERT INTO units(id,product_id,outlet_id,code,status,condition_note,purchase_price,partner_id,created_at) SELECT id,product_id,outlet_id,code,status,condition_note,purchase_price,partner_id,created_at FROM _copy_units;
DROP TABLE _copy_units;
INSERT INTO customers(id,name,phone,email,address,id_doc,blacklisted,notes,segment,created_at) SELECT id,name,phone,email,address,id_doc,blacklisted,notes,segment,created_at FROM _copy_customers;
DROP TABLE _copy_customers;
INSERT INTO bookings(id,outlet_id,customer_id,code,status,channel,start_at,end_at,subtotal,discount,total,paid,dp,expires_at,collateral,collateral_type,note,idem,created_at) SELECT id,outlet_id,customer_id,code,status,channel,start_at,end_at,subtotal,discount,total,paid,dp,expires_at,collateral,collateral_type,note,idem,created_at FROM _copy_bookings;
DROP TABLE _copy_bookings;
INSERT INTO items(id,booking_id,product_id,unit_id,product_name,price,days,total,returned_at,condition,voided_at) SELECT id,booking_id,product_id,unit_id,product_name,price,days,total,returned_at,condition,voided_at FROM _copy_items;
DROP TABLE _copy_items;
INSERT INTO reservations(id,unit_id,booking_id,start_at,end_at,kind,released_at) SELECT id,unit_id,booking_id,start_at,end_at,kind,released_at FROM _copy_reservations;
DROP TABLE _copy_reservations;
INSERT INTO payments(id,booking_id,amount,method,kind,status,proof,idem,created_at) SELECT id,booking_id,amount,method,kind,status,proof,idem,created_at FROM _copy_payments;
DROP TABLE _copy_payments;
INSERT INTO ledger(id,booking_id,account,direction,amount,reference,note,created_at) SELECT id,booking_id,account,direction,amount,reference,note,created_at FROM _copy_ledger;
DROP TABLE _copy_ledger;
INSERT INTO status_logs(id,booking_id,status,note,created_at) SELECT id,booking_id,status,note,created_at FROM _copy_status_logs;
DROP TABLE _copy_status_logs;
INSERT INTO audit(id,user_id,action,entity_id,ip,created_at) SELECT id,user_id,action,entity_id,ip,created_at FROM _copy_audit;
DROP TABLE _copy_audit;
INSERT INTO uploads(id,kind,owner_token,mime,created_at,storage_key) SELECT id,kind,owner_token,mime,created_at,tenant_id||'/'||id FROM _copy_uploads;
DROP TABLE _copy_uploads;
INSERT INTO rate_limits(key,count,expires_at) SELECT key,count,expires_at FROM _copy_rate_limits;
DROP TABLE _copy_rate_limits;
INSERT INTO operation_keys(key) SELECT key FROM _copy_operation_keys;
DROP TABLE _copy_operation_keys;
CREATE INDEX records_business ON records(kind,deleted_at);
CREATE INDEX products_business ON products(deleted_at,category);
CREATE INDEX units_business ON units(product_id,outlet_id,status);
CREATE INDEX customers_business ON customers(name);
CREATE INDEX bookings_business ON bookings(status,start_at);
CREATE INDEX items_business ON items(booking_id);
CREATE INDEX reservations_business ON reservations(unit_id,start_at,end_at) WHERE released_at IS NULL;
CREATE TRIGGER no_overlap_insert BEFORE INSERT ON reservations WHEN NEW.released_at IS NULL AND EXISTS(SELECT 1 FROM reservations r WHERE r.unit_id=NEW.unit_id AND r.released_at IS NULL AND r.start_at<NEW.end_at AND NEW.start_at<r.end_at) BEGIN SELECT RAISE(ABORT,'UNIT_NOT_AVAILABLE'); END;
CREATE TRIGGER no_overlap_update BEFORE UPDATE OF start_at,end_at,released_at ON reservations WHEN NEW.released_at IS NULL AND EXISTS(SELECT 1 FROM reservations r WHERE r.id<>NEW.id AND r.unit_id=NEW.unit_id AND r.released_at IS NULL AND r.start_at<NEW.end_at AND NEW.start_at<r.end_at) BEGIN SELECT RAISE(ABORT,'UNIT_NOT_AVAILABLE'); END;
CREATE INDEX payments_business ON payments(status,booking_id);
CREATE INDEX ledger_business ON ledger(created_at);
CREATE TRIGGER ledger_no_update BEFORE UPDATE ON ledger BEGIN SELECT RAISE(ABORT,'LEDGER_IMMUTABLE'); END;
CREATE TRIGGER ledger_no_delete BEFORE DELETE ON ledger BEGIN SELECT RAISE(ABORT,'LEDGER_IMMUTABLE'); END;
CREATE INDEX logs_business ON status_logs(booking_id,created_at);
CREATE INDEX audit_business ON audit(created_at);
CREATE INDEX uploads_business ON uploads(kind);
CREATE TRIGGER voucher_quota BEFORE UPDATE OF data ON records WHEN NEW.kind='voucher' AND COALESCE(json_extract(NEW.data,'$.quota'),0)>0 AND COALESCE(json_extract(NEW.data,'$.used'),0)>json_extract(NEW.data,'$.quota') AND COALESCE(json_extract(NEW.data,'$.used'),0)>COALESCE(json_extract(OLD.data,'$.used'),0) BEGIN SELECT RAISE(ABORT,'VOUCHER_QUOTA'); END;
CREATE INDEX items_active ON items(booking_id,voided_at);
CREATE TABLE sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),token_hash TEXT NOT NULL UNIQUE,csrf_token TEXT NOT NULL,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE UNIQUE INDEX users_email_nocase ON users(lower(email));
CREATE INDEX bookings_outlet_status ON bookings(outlet_id,status,start_at);
CREATE INDEX units_outlet_product ON units(outlet_id,product_id,status);
